[
  {
    "pda_self_consequence_regret": "My main regret, if it comes to that, is all the things I won't get"
  },
  {
    "pd_personal_consequence_anxiety": "losing that chance to see them grow up eats at me already",
    "sys_consistent_procedure": "I'd rather we draw straws than let panic make the choice"
  },
  {
    "pda_self_consequence_regret": "nobody back home will ever know I tried to keep things calm out here",
    "sys_consequence_reasoning": "five people getting home matters more than whether my name gets remembered right"
  },
  {
    "pda_self_consequence_regret": "My regret is that people might call me a coward later"
  },
  {
    "pd_personal_consequence_anxiety": "Losing the chance to walk my daughter down the aisle someday is the thing"
  },
  {
    "pda_self_consequence_regret": "What I'll regret is the unfinished business"
  },
  {
    "pda_self_consequence_regret": "My biggest regret would be losing my shot at the promotion"
  },
  {
    "pda_self_consequence_regret": "decision might cost me some trust with the others once we're all safe"
  },
  {
    "pda_self_consequence_regret": "knowing I'll miss my own future entirely"
  },
  {
    "pd_personal_consequence_anxiety": "What worries me most is the idea of being remembered as someone who hesitated",
    "sys_consequence_reasoning": "five getting out matters more than any one of us feeling certain first"
  }
]
